scripts.onUpdate:
function getTilemap(entity) {
  const direct = entity && entity.getComponent && entity.getComponent("Tilemap2DComponent");
  if (direct) return direct;
  for (const item of entity && entity.components && entity.components.values ? entity.components.values() : []) {
    if (item && (item.name === "Tilemap2DComponent" || String(item.UniqueSymbol) === "Symbol(Tilemap2DComponent)")) return item;
  }
  return null;
}

function getCanvasText(entity) {
  const direct = entity && entity.getComponent && entity.getComponent("CanvasTextComponent");
  if (direct) return direct;
  for (const item of entity && entity.components && entity.components.values ? entity.components.values() : []) {
    if (item && (item.name === "CanvasTextComponent" || String(item.UniqueSymbol) === "Symbol(CanvasTextComponent)")) return item;
  }
  return null;
}

const config = api.read.data() || {};
const boardEntity = api.read && api.read.find("Minesweeper Board");
const board = getTilemap(boardEntity);
const statusTextEntity = api.read && api.read.find("Minesweeper Status Text");
const minesTextEntity = api.read && api.read.find("Minesweeper Mines Text");
const cellTextEntities = [];
for (let i = 0; i < 81; i++) cellTextEntities.push(api.read && api.read.find("Minesweeper Cell " + i));

if (!board) {
  api.debug.console.warn("Minesweeper Starter requires Minesweeper Board with Tilemap2DComponent.");
  return;
}

const state = component.state || (component.state = {});
const rows = Number(config.rows || 9);
const cols = Number(config.columns || 9);
const mineCount = Number(config.mines || 10);
const palette = config.paletteIndex || { hidden: 1, revealed: 2, flag: 3, mine: 4, exploded: 5 };
const numberColors = config.numberColors || {
  1: "#2563eb",
  2: "#15803d",
  3: "#dc2626",
  4: "#4338ca",
  5: "#b91c1c",
  6: "#0f766e",
  7: "#111827",
  8: "#6b7280"
};

function makeCells() {
  return Array.from({ length: rows }, function (_, y) {
    return Array.from({ length: cols }, function (_, x) {
      return { x: x, y: y, mine: false, revealed: false, flagged: false, adjacent: 0, exploded: false };
    });
  });
}

function cellAt(x, y) {
  return x >= 0 && y >= 0 && x < cols && y < rows ? state.cells[y][x] : null;
}

function neighbors(x, y) {
  const result = [];
  for (let yy = y - 1; yy <= y + 1; yy++) {
    for (let xx = x - 1; xx <= x + 1; xx++) {
      if (xx === x && yy === y) continue;
      const cell = cellAt(xx, yy);
      if (cell) result.push(cell);
    }
  }
  return result;
}

function reset() {
  state.cells = makeCells();
  state.phase = "ready";
  state.generated = false;
  state.revealedCount = 0;
  state.flaggedCount = 0;
}


function generate(firstX, firstY) {
  const excluded = new Set([firstY + "," + firstX]);
  for (const n of neighbors(firstX, firstY)) excluded.add(n.y + "," + n.x);
  const candidates = [];
  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      if (!excluded.has(y + "," + x)) candidates.push(state.cells[y][x]);
    }
  }
  for (let i = candidates.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    const tmp = candidates[i];
    candidates[i] = candidates[j];
    candidates[j] = tmp;
  }
  for (let i = 0; i < Math.min(mineCount, candidates.length); i++) candidates[i].mine = true;
  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      state.cells[y][x].adjacent = neighbors(x, y).filter(function (cell) { return cell.mine; }).length;
    }
  }
  state.generated = true;
  state.phase = "playing";
}

function reveal(x, y) {
  if (state.phase === "won" || state.phase === "lost") return;
  if (!state.generated) generate(x, y);
  const start = cellAt(x, y);
  if (!start || start.flagged || start.revealed) return;
  if (start.mine) {
    start.exploded = true;
    state.phase = "lost";
    revealAllMines();
    return;
  }
  const queue = [start];
  while (queue.length) {
    const cell = queue.shift();
    if (!cell || cell.revealed || cell.flagged) continue;
    cell.revealed = true;
    state.revealedCount++;
    if (cell.adjacent === 0) {
      for (const next of neighbors(cell.x, cell.y)) {
        if (!next.revealed && !next.flagged && !next.mine) queue.push(next);
      }
    }
  }
  if (state.revealedCount >= rows * cols - mineCount) {
    state.phase = "won";
    for (let yy = 0; yy < rows; yy++) for (let xx = 0; xx < cols; xx++) if (state.cells[yy][xx].mine) state.cells[yy][xx].flagged = true;
    state.flaggedCount = mineCount;
  }
}

function toggleFlag(x, y) {
  if (state.phase === "won" || state.phase === "lost") return;
  const cell = cellAt(x, y);
  if (!cell || cell.revealed) return;
  cell.flagged = !cell.flagged;
  state.flaggedCount += cell.flagged ? 1 : -1;
  if (state.phase === "ready") state.phase = "playing";
}

function chordReveal(x, y) {
  if (state.phase !== "playing") return;
  const cell = cellAt(x, y);
  if (!cell || !cell.revealed || cell.mine || cell.adjacent <= 0) return;
  const nearby = neighbors(x, y);
  const flags = nearby.filter(function (item) { return item.flagged; }).length;
  if (flags !== cell.adjacent) return;
  for (const item of nearby) {
    if (!item.revealed && !item.flagged) reveal(item.x, item.y);
    if (state.phase === "lost") return;
  }
}

function revealAllMines() {
  for (let y = 0; y < rows; y++) for (let x = 0; x < cols; x++) if (state.cells[y][x].mine) state.cells[y][x].revealed = true;
}

function setTilemapTransform(entity, x, y) {
  const transform = entity && entity.getComponent && entity.getComponent("Transform2D");
  if (!transform) return;
  transform.x = x;
  transform.y = y;
}

function layoutTilemap(tilemap, cellWidth, cellHeight, gap) {
  if (!tilemap) return;
  tilemap.cellWidth = cellWidth;
  tilemap.cellHeight = cellHeight;
  tilemap.gap = gap;
}

function setTextBox(entity, value, x, y, width, height, fontSize, color) {
  if (!entity) return;
  entity.disabled = !value;
  const transform = entity.getComponent && entity.getComponent("Transform2D");
  if (transform) {
    transform.x = x;
    transform.y = y;
  }
  const text = getCanvasText(entity);
  if (!text) return;
  text.text = String(value || "");
  const style = text.style || {};
  const next = {
    ...style,
    width: Math.max(1, Math.floor(width)),
    height: Math.max(1, Math.floor(height)),
    resolutionScale: Number(config.textResolutionScale || 2),
    backgroundColor: "rgba(255,255,255,0)",
    borderWidth: 0,
    padding: 0,
    textAlign: "center",
    verticalAlign: "middle",
    fontSize: Math.max(8, Math.floor(fontSize)),
    fontFamily: "system-ui, sans-serif",
    fontWeight: "800",
    lineHeight: 1,
    color: color || "#111827",
    whiteSpace: "pre-line"
  };
  if (style.width !== next.width || style.height !== next.height || style.fontSize !== next.fontSize || style.color !== next.color || style.resolutionScale !== next.resolutionScale) {
    text.style = next;
  }
}

function getViewportMetrics() {
  const canvas = document.getElementById("player-canvas");
  const rect = canvas && canvas.getBoundingClientRect ? canvas.getBoundingClientRect() : { left: 0, top: 0, width: window.innerWidth, height: window.innerHeight };
  const fallbackWidth = Math.max(1, canvas && canvas.clientWidth || rect.width || window.innerWidth || 390);
  const fallbackHeight = Math.max(1, canvas && canvas.clientHeight || rect.height || window.innerHeight || 844);
  const cameras = api.read && api.read.findByComponent ? api.read.findByComponent("Camera2D") : [];
  const cameraEntity = cameras && cameras[0];
  const camera = cameraEntity && cameraEntity.getComponent && cameraEntity.getComponent("Camera2D");
  const width = Math.max(1, Number(camera && camera.width) || fallbackWidth);
  const height = Math.max(1, Number(camera && camera.height) || fallbackHeight);
  return { canvas: canvas, rect: rect, width: width, height: height };
}

function updateLayout() {
  const viewport = getViewportMetrics();
  const width = viewport.width;
  const height = viewport.height;
  const portrait = height >= width;
  const margin = portrait ? 18 : 30;
  const hudReserve = portrait ? 170 : 90;
  const cell = Math.max(24, Math.floor(Math.min((width - margin * 2) / cols, (height - hudReserve) / rows, portrait ? 54 : 64)));
  const gap = Math.max(2, Math.floor(cell * 0.06));
  const boardWidth = cols * cell;
  const boardHeight = rows * cell;
  const boardX = -boardWidth / 2;
  const boardY = portrait ? -boardHeight / 2 - 8 : -boardHeight / 2 - 18;
  state.layout = { boardX: boardX, boardY: boardY, cell: cell, rows: rows, cols: cols };
  layoutTilemap(board, cell, cell, gap);
  setTilemapTransform(boardEntity, boardX, boardY);

  const panelWidth = Math.min(width - 36, Math.max(220, boardWidth));
  const panelHeight = Math.max(26, Math.floor(cell * 0.48));
  const panelFont = Math.max(13, Math.floor(cell * 0.28));
  setTextBox(statusTextEntity, statusLabel(), -panelWidth / 2, boardY + boardHeight + 14, panelWidth, panelHeight, panelFont, state.phase === "lost" ? "#dc2626" : state.phase === "won" ? "#15803d" : "#374151");
  setTextBox(minesTextEntity, "MINES " + Math.max(0, mineCount - state.flaggedCount), -panelWidth / 2, boardY + boardHeight + 14 + panelHeight + 6, panelWidth, panelHeight, panelFont, "#374151");
}

function worldToCell(clientX, clientY) {
  const viewport = getViewportMetrics();
  const rect = viewport.rect;
  const layout = state.layout;
  if (!layout || rect.width <= 0 || rect.height <= 0) return null;
  const worldX = ((clientX - rect.left) / rect.width - 0.5) * viewport.width;
  const worldY = (0.5 - (clientY - rect.top) / rect.height) * viewport.height;
  const col = Math.floor((worldX - layout.boardX) / layout.cell);
  const visualRow = Math.floor((worldY - layout.boardY) / layout.cell);
  const row = rows - 1 - visualRow;
  return col >= 0 && row >= 0 && col < cols && row < rows ? { x: col, y: row } : null;
}

function isSecondaryPointer(event) {
  return event.button === 2 || (event.buttons & 2) === 2 || event.ctrlKey || event.metaKey;
}

function runSecondaryAction(cell) {
  const target = cellAt(cell.x, cell.y);
  if (target && target.revealed && target.adjacent > 0) chordReveal(cell.x, cell.y);
  else toggleFlag(cell.x, cell.y);
}

function installPointerInput() {
  const canvas = document.getElementById("player-canvas");
  if (!canvas || !canvas.addEventListener) return;
  if (state.pointerReady && state.pointerCanvas === canvas) return;
  if (state.pointerCanvas && state.contextMenuHandler && state.pointerDownHandler && state.pointerUpHandler && state.pointerCancelHandler && state.pointerCanvas.removeEventListener) {
    state.pointerCanvas.removeEventListener("contextmenu", state.contextMenuHandler);
    state.pointerCanvas.removeEventListener("pointerdown", state.pointerDownHandler);
    state.pointerCanvas.removeEventListener("pointerup", state.pointerUpHandler);
    state.pointerCanvas.removeEventListener("pointercancel", state.pointerCancelHandler);
  }
  state.contextMenuHandler = function (event) { event.preventDefault(); };
  state.pointerCancelHandler = function () {
    state.suppressNextPointerUp = false;
    state.pointerDownCell = null;
  };
  state.pointerDownHandler = function (event) {
    const cell = worldToCell(event.clientX, event.clientY);
    state.pointerDownCell = cell;
    state.suppressNextPointerUp = false;
    if (!cell || !isSecondaryPointer(event)) return;
    event.preventDefault();
    state.suppressNextPointerUp = true;
    runSecondaryAction(cell);
  };
  state.pointerUpHandler = function (event) {
    if (state.suppressNextPointerUp) {
      state.suppressNextPointerUp = false;
      state.pointerDownCell = null;
      event.preventDefault();
      return;
    }
    const cell = worldToCell(event.clientX, event.clientY) || state.pointerDownCell;
    state.pointerDownCell = null;
    if (!cell) return;
    event.preventDefault();
    if (isSecondaryPointer(event)) runSecondaryAction(cell);
    else reveal(cell.x, cell.y);
  };
  api.debug.listen(canvas, "contextmenu", state.contextMenuHandler);
  api.debug.listen(canvas, "pointerdown", state.pointerDownHandler);
  api.debug.listen(canvas, "pointerup", state.pointerUpHandler);
  api.debug.listen(canvas, "pointercancel", state.pointerCancelHandler);
  state.pointerCanvas = canvas;
  state.pointerReady = true;
  api.debug.addDisposer(function () {
    state.pointerReady = false;
    state.pointerCanvas = null;
    state.pointerStart = null;
  });
}

function statusLabel() {
  if (state.phase === "ready") return "Click a cell to start";
  if (state.phase === "won") return "Cleared! Press R";
  if (state.phase === "lost") return "Mine hit! Press R";
  return "Left click reveal / right click flag";
}

function draw() {
  updateLayout();
  board.clear(palette.hidden);
  const layout = state.layout;
  const fontSize = Math.max(14, Math.floor(layout.cell * 0.42));
  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      const cell = state.cells[y][x];
      let tile = palette.hidden;
      let label = "";
      let color = "#111827";
      if (cell.revealed) {
        tile = cell.exploded ? palette.exploded : cell.mine ? palette.mine : palette.revealed;
        if (cell.mine) {
          label = "*";
          color = cell.exploded ? "#ffffff" : "#111827";
        } else if (cell.adjacent > 0) {
          label = String(cell.adjacent);
          color = numberColors[cell.adjacent] || "#111827";
        }
      } else if (cell.flagged) {
        tile = palette.flag;
        label = "F";
        color = "#ffffff";
      }
      board.setCell(x, rows - 1 - y, tile);
      const index = y * cols + x;
      const textX = layout.boardX + x * layout.cell;
      const textY = layout.boardY + (rows - 1 - y) * layout.cell;
      setTextBox(cellTextEntities[index], label, textX, textY, layout.cell, layout.cell, fontSize, color);
    }
  }
}

if (!state.ready) {
  reset();
  state.ready = true;
  api.debug.console.log("Minesweeper Starter ready.");
}
installPointerInput();
if (api.input.wasPressed("Restart") || api.input.wasPressed("KeyR")) reset();
draw();
